/* Reference-aligned UI prototype. No network calls or authorization claims.
 * Fixtures are authored for this demo; no internal platform data is bundled. */
(() => {
  'use strict';
  const scopes={personal:'个人知识库',shared:'共享知识库',dept:'部门知识库'};
  const departments=[{id:'office',name:'综合办公室',exists:true},{id:'service',name:'业务服务部',exists:true},{id:'operations',name:'运营管理部',exists:false}];
  let serial=20;
  const nodes=[
    {id:'p1',scope:'personal',parent:null,name:'我的工作资料',kind:'folder',summary:'日常工作中整理的会议筹备与任务跟进资料。',overview:'这里收录会议筹备要点和个人工作记录，便于在处理日常事务时快速查阅。'},
    {id:'p2',scope:'personal',parent:'p1',name:'会议筹备清单.txt',kind:'file',summary:'会议筹备的会前、会中与会后检查事项。',text:'会议筹备清单\n会前：确认会议目的、议题、参会范围、时间及场地，准备会议材料并检查设备。\n会中：记录讨论要点、议定事项和待确认问题。\n会后：整理纪要，核实任务责任人与时间要求，持续跟进落实情况。'},
    {id:'s1',scope:'shared',parent:null,name:'公共办公指南',kind:'folder',summary:'供成员共同查阅的办公协作指南。',overview:'汇集文档协作和材料整理方法。共享资料与个人资料分开管理。'},
    {id:'s2',scope:'shared',parent:'s1',name:'文档协作指南.txt',kind:'file',summary:'文档命名、版本整理与协作交接的基础方法。',text:'文档协作指南\n使用清晰的文件名称，标注主题与版本。\n审定稿与过程稿分开存放，更新时记录修改内容。\n交接时说明当前进度、待办事项与资料所在目录。'},
    {id:'d1',scope:'dept',dept:'office',parent:null,name:'部门工作规范',kind:'folder',summary:'综合办公室的工作材料与会议服务规范。',overview:'面向部门日常工作，整理材料流转和会议服务相关事项。'},
    {id:'d2',scope:'dept',dept:'office',parent:'d1',name:'材料流转说明.txt',kind:'file',summary:'收集、核对、确认、归档四个环节。',text:'材料流转说明\n先收集业务材料，再核对事实与附件。\n由相应负责人确认内容后形成审定稿。\n归档时保留原始材料、审定版本与修改记录。'},
    {id:'d3',scope:'dept',dept:'service',parent:null,name:'业务协作资料',kind:'folder',summary:'业务服务部的资料目录。',overview:'目前尚未添加文件。'}
  ];
  const state={scope:'personal',dept:null,selected:{},expanded:new Set(['p1','s1','d1','d3']),filter:'',pending:[],uploadTarget:null,uploadToken:0,uploadBusy:false,uploadContext:null,filePage:1,fileSize:10,fileQ:'',fileScope:'',fileStatus:'',sessions:[],active:null,draft:'',busy:false,request:0};
  function scopeKey(){return state.scope==='dept'?'dept:'+state.dept:state.scope;}
  function inScope(n){return n.scope===state.scope&&(n.scope!=='dept'||n.dept===state.dept);}
  function selected(){return nodes.find(n=>n.id===state.selected[scopeKey()]&&inScope(n));}
  function visibleNodes(){return nodes.filter(inScope);}
  function escText(s){return esc(String(s??''));}
  const action=(t,f,cls='')=>`<button class="btn ${cls}" onclick="KW.${f}">${t}</button>`;
  function tabs(view){return `<nav class="kw-tabs" aria-label="知识库导航">${[['overview','营运总览'],...Object.entries(scopes)].map(([id,t])=>`<button class="${view===id?'on':''}" ${view===id?'aria-current="page"':''} onclick="KW.open('${id}')">${t}</button>`).join('')}</nav>`;}
  function top(title,sub,buttons=''){return `<header class="kw-head"><div><h2>${title}</h2><p>${sub}</p></div><div class="kw-actions">${buttons}</div></header>`;}
  function empty(title,desc){return `<div class="kw-empty">${ic('db','ic ic-xl')}<h3>${title}</h3><p>${desc}</p></div>`;}
  function dlg(title,body,footer=''){openDlg(`<div class="pnl-h"><h3>${title}</h3><button class="x" aria-label="关闭" onclick="closeAll()">×</button></div><div class="pnl-b">${body}</div>${footer?`<div class="pnl-f">${footer}</div>`:''}`,540);}
  function treeHTML(){
    const list=visibleNodes(),q=state.filter.trim().toLowerCase();
    function keep(n){return !q||(n.name+' '+(n.summary||'')).toLowerCase().includes(q)||list.some(c=>c.parent===n.id&&keep(c));}
    function branch(parent,depth){return list.filter(n=>n.parent===parent&&keep(n)).map(n=>{
      const folder=n.kind==='folder',open=state.expanded.has(n.id)||!!q;
      return `<div class="kw-tree-row ${selected()?.id===n.id?'on':''}" style="padding-left:${5+depth*14}px"><button class="kw-toggle" aria-label="${folder?(open?'收起':'展开')+escText(n.name):'文件'}" ${folder?`aria-expanded="${open}" onclick="KW.toggle('${n.id}')"`:'disabled'}>${folder?(open?'▾':'▸'):'·'}</button><button class="kw-node" onclick="KW.select('${n.id}')" title="${escText(n.name)}">${ic(folder?'db':'doc','ic ic-s')}<span>${escText(n.name)}</span></button><div class="kw-node-tools">${!folder?`<button title="下载原始文件" aria-label="下载 ${escText(n.name)}" onclick="KW.download('${n.id}')">${ic('dl','ic ic-s')}</button>`:''}<button title="删除" aria-label="删除 ${escText(n.name)}" onclick="KW.remove('${n.id}')">${ic('trash','ic ic-s')}</button></div></div>${folder&&open?branch(n.id,depth+1):''}`;
    }).join('');}
    return branch(null,0)||`<p class="kw-muted" style="padding:20px 6px">${q?'没有匹配的目录或文件':'暂无目录，点击“新建目录”开始整理'}</p>`;
  }
  function detailHTML(){
    if(state.scope==='dept'&&!state.dept)return empty('先选择一个部门','选择后查看该部门的资料目录与内容概览。');
    const n=selected();if(!n)return empty('从左侧选择目录或文件','这里显示内容摘要与详细概览，不必在多个列表之间切换。');
    const parent=nodes.find(x=>x.id===n.parent);
    return `<header><div><div class="kw-muted">${scopes[n.scope]}${parent?' / '+escText(parent.name):''}</div><h3>${escText(n.name)}</h3><p class="kw-muted">${n.kind==='folder'?'目录':n.pending?'等待内容处理':'文件'}${n.size?' · '+escText(n.size):''}</p></div><div class="kw-actions">${n.kind==='folder'?action('上传资源','upload()'):action('下载原始文件',`download('${n.id}')`)}${action('刷新','refresh()')}</div></header><h4>内容摘要</h4><div class="kw-summary">${escText(n.summary||'暂无摘要')}</div><h4>详细概览</h4><article><div class="kw-details-text">${escText(n.overview||(n.kind==='file'?n.text:'')||'暂无概览')}</div>${n.kind==='folder'?`<p class="kw-muted">当前目录包含 ${nodes.filter(x=>x.parent===n.id).length} 个直接子项，可在左侧展开查看。</p>`:''}</article>`;
  }
  function workspaceHTML(){
    const blocked=state.scope==='dept'&&!state.dept;
    return `<section class="kw">${top('知识库管理','整理资料、查看内容，管理个人、共享与部门知识库。')}${tabs(state.scope)}<div class="kw-workspace"><aside class="kw-tree">${state.scope==='dept'?`<div class="kw-actions">${action(escText(departments.find(d=>d.id===state.dept)?.name||'选择部门'),'chooseDept()')}${action('添加部门库','addDept()')}</div>`:''}<h3>${scopes[state.scope]}</h3><div class="kw-actions" style="margin-bottom:14px"><button class="btn sm" ${blocked?'disabled':''} onclick="KW.newFolder()">新建目录</button><button id="kwTreeUpload" class="btn sm" ${!selected()?'disabled':''} onclick="KW.upload()">上传</button>${action('刷新','refresh()','sm')}</div><input class="inp" aria-label="按名称或摘要筛选目录" placeholder="搜索目录或文件" value="${escText(state.filter)}" oninput="KW.filter(this.value)"><div id="kwTree">${blocked?'<p class="kw-muted">请选择部门后查看目录</p>':treeHTML()}</div></aside><main class="kw-detail" id="kwDetail">${detailHTML()}</main></div></section>`;
  }
  function fileSource(n){
    if(n.scope!=='dept')return scopes[n.scope];
    return `部门知识库 · ${departments.find(d=>d.id===n.dept)?.name||'未命名部门'}`;
  }
  function fileFolder(n){return nodes.find(x=>x.id===n.parent)?.name||'根目录';}
  function accessibleFiles(){return nodes.filter(n=>n.kind==='file');}
  function overviewHTML(){
    return `<section class="kw">${top('知识库营运总览','查看当前账户可使用的资料范围与知识库使用情况。',action('刷新','refresh()'))}${tabs('overview')}<div class="kw-metrics">${[
      ['上下文数据量',nodes.filter(n=>n.kind==='file').length+4,`文件 ${nodes.filter(n=>n.kind==='file').length}　记忆 2　技能 2`],['今日 Tokens 消耗','2,480','VLM 输入 1,600　输出 640　Embedding 输入 240'],['今日检索次数','18','find 12　search 6']
    ].map(([t,v,d])=>`<div class="kw-metric"><h3>${t}</h3><strong>${v}</strong><small>${d}</small></div>`).join('')}</div><div class="kw-card"><h3>Tokens 总消耗统计</h3><p class="kw-muted">最近 14 天 · 每日用量</p><div class="kw-chart" role="img" aria-label="最近14天 VLM 输入、输出及 Embedding 输入柱状图">${Array.from({length:14},(_,i)=>{const v=[(i*17%60)+20,(i*11%23)+9,(i*7%10)+3];return `<div class="kw-day" title="9月${i+7}日：输入 ${v[0]*40}，输出 ${v[1]*40}，Embedding ${v[2]*40}">${v.map((h,j)=>`<i style="height:${h}%;background:${['#3d71bd','#77b7aa','#a997c8'][j]}"></i>`).join('')}<span>09-${i+7}</span></div>`;}).join('')}</div><div class="kw-legend">${['VLM 输入','VLM 输出','Embedding 输入'].map((t,i)=>`<span><b style="background:${['#3d71bd','#77b7aa','#a997c8'][i]}"></b>${t}</span>`).join('')}</div></div><div class="kw-card"><h3>上下文提交统计</h3><p class="kw-muted">最近一年 · 文件、技能、会话消息和提交写入</p><div class="kw-heatmap" aria-label="年度提交分布">${Array.from({length:364},(_,i)=>`<i title="第 ${i+1} 天：${i%9===0?'4 次资源提交，2 条会话消息':'无提交'}" style="background:${i%9===0?'#739ace':i%17===0?'#c6d8ef':'#edf2f7'}"></i>`).join('')}</div><p class="kw-muted">颜色越深，提交越多；悬停查看当日记录。</p></div><div class="kw-card"><h3>当前账户可查看的文件</h3><p class="kw-muted">汇总个人、共享及有权访问的部门资料；点击“查看”进入文件所在目录。</p><div class="kw-filters"><input id="kwFileQ" class="inp" placeholder="搜索文件名称或内容摘要" aria-label="搜索可查看文件" value="${escText(state.fileQ)}"><select id="kwFileScope" class="sel" aria-label="文件来源"><option value="">全部来源</option><option value="personal" ${state.fileScope==='personal'?'selected':''}>个人知识库</option><option value="shared" ${state.fileScope==='shared'?'selected':''}>共享知识库</option><option value="dept" ${state.fileScope==='dept'?'selected':''}>部门知识库</option></select><select id="kwFileStatus" class="sel" aria-label="文件状态"><option value="">全部状态</option><option value="ready" ${state.fileStatus==='ready'?'selected':''}>可用于问答</option><option value="pending" ${state.fileStatus==='pending'?'selected':''}>等待处理</option></select>${action('查询','filesQuery()','pri')}${action('重置','filesReset()')}</div><div id="kwAccessibleFiles">${filesHTML()}</div></div></section>`;
  }
  function filesHTML(){
    const q=state.fileQ.toLowerCase(),list=accessibleFiles().filter(n=>(!q||(n.name+' '+(n.summary||'')).toLowerCase().includes(q))&&(!state.fileScope||n.scope===state.fileScope)&&(!state.fileStatus||(state.fileStatus==='pending'===!!n.pending))),pages=Math.max(1,Math.ceil(list.length/state.fileSize));
    state.filePage=Math.min(state.filePage,pages);
    return `<div class="kw-file-table"><div class="kw-file-head"><span>文件名称</span><span>资料来源</span><span>所在目录</span><span>状态</span><span>操作</span></div>${list.slice((state.filePage-1)*state.fileSize,state.filePage*state.fileSize).map(n=>`<div class="kw-file-row"><span class="kw-file-name">${ic('doc','ic ic-s')}<b title="${escText(n.name)}">${escText(n.name)}</b><small>${escText(n.summary||'暂无摘要')}</small></span><span>${escText(fileSource(n))}</span><span>${escText(fileFolder(n))}</span><span><span class="tag ${n.pending?'':'g'}">${n.pending?'等待处理':'可用于问答'}</span></span><span><button class="btn sm gho" onclick="KW.openFile('${n.id}')">查看</button></span></div>`).join('')||'<div class="kw-file-empty">没有符合条件的文件</div>'}</div><div class="kw-pager"><span>共 ${list.length} 个文件</span><select class="sel" aria-label="每页文件数" onchange="KW.fileSize(this.value)">${[10,20,50].map(n=>`<option value="${n}" ${n===state.fileSize?'selected':''}>${n} 个/页</option>`).join('')}</select><button class="btn sm" ${state.filePage===1?'disabled':''} onclick="KW.filePage(-1)">上一页</button><span>${state.filePage} / ${pages}</span><button class="btn sm" ${state.filePage>=pages?'disabled':''} onclick="KW.filePage(1)">下一页</button></div>`;
  }
  function session(){return state.sessions.find(s=>s.id===state.active);}
  function ensureSession(){if(!session()){const s={id:'session-'+(++serial),title:'新会话',at:new Date().toLocaleString('zh-CN'),messages:[]};state.sessions.unshift(s);state.active=s.id;}return session();}
  function chatHTML(){const s=session();return `<section class="kw kw-qa">${top('知识库问答','自动检索当前账号有权限访问的知识库。',`<button class="btn" ${state.busy?'disabled':''} onclick="KW.history()">历史会话</button><button class="btn pri" ${state.busy?'disabled':''} onclick="KW.newChat()">新建会话</button>`)}<div class="kw-chat"><div class="kw-chat-body" id="kwChatBody">${messagesHTML(s)}</div><div class="kw-composer"><textarea id="kwQuestion" aria-label="输入问题" placeholder="输入问题后回车发送，Shift + Enter 换行" oninput="KW.draft(this.value)">${escText(state.draft)}</textarea><footer><span class="kw-muted">仅使用当前账号可访问的资料</span><button id="kwSend" class="btn ${state.busy?'':'pri'}" ${!state.busy&&!state.draft.trim()?'disabled':''} onclick="KW.${state.busy?'stop()':'send()'}">${state.busy?'停止回答':'发送'}</button></footer></div></div></section>`;}
  function messagesHTML(s){if(!s?.messages.length)return `<div class="kw-welcome"><span style="color:var(--brand)">${ic('chat','ic ic-xl')}</span><h2>从已有知识中找到答案</h2><p>查找资料、归纳要点，也可以接着上文继续提问。</p><div class="kw-suggestions">${['知识库里有哪些文档？','帮我总结会议筹备的要点','材料流转需要哪些步骤？'].map(q=>`<button onclick="KW.ask(this.textContent)">${q}</button>`).join('')}</div></div>`;return s.messages.map((m,i)=>`<div class="kw-message ${m.role==='user'?'user':''}"><small>${m.role==='user'?'我':'知识库助手'}</small>${m.role==='assistant'?`<details class="kw-process"><summary>${m.loading?'正在查找可用资料…':m.stopped?'已停止':m.pending?'未获得可用回答':'资料处理记录'}</summary><ul>${(m.steps||[]).map(t=>`<li>${escText(t)}</li>`).join('')}</ul></details>`:''}<div class="kw-bubble">${escText(m.loading?'正在处理，请稍候…':m.text)}</div>${m.sources?.length?`<div>${m.sources.map(id=>{const n=nodes.find(x=>x.id===id);return n?`<button class="kw-source" onclick="KW.source('${id}')">${ic('doc','ic ic-s')}${escText(n.name)}</button>`:'';}).join('')}</div>`:''}${m.role==='assistant'&&!m.loading?action('复制',`copy(${i})`,'sm gho'):''}</div>`).join('');}
  const KW=window.KW={
    open(scope){if(state.busy)KW.stop();if(scope==='overview')return go('kb');state.scope=scope;if(scope!=='dept')state.dept=null;state.filter='';go('kb-library');},
    filter(value){state.filter=value;$('#kwTree').innerHTML=treeHTML();},
    toggle(id){state.expanded.has(id)?state.expanded.delete(id):state.expanded.add(id);$('#kwTree').innerHTML=treeHTML();},
    select(id){const n=nodes.find(n=>n.id===id&&inScope(n));if(!n)return;state.selected[scopeKey()]=id;$('#kwTree').innerHTML=treeHTML();$('#kwDetail').innerHTML=detailHTML();const upload=$('#kwTreeUpload');if(upload)upload.disabled=false;},
    refresh(){render();toast('视图已刷新','ok');},
    newFolder(){if(state.scope==='dept'&&!state.dept)return;const n=selected(),parent=n?(n.kind==='folder'?n:nodes.find(p=>p.id===n.parent)):null;state.folderContext={scope:state.scope,dept:state.dept,parent:parent?.id||null};dlg('新建目录',`<p class="kw-muted">创建到：${escText(parent?.name||scopes[state.scope])}</p><div class="fld"><label for="kwFolderName">目录名称 *</label><input class="inp" id="kwFolderName" maxlength="80" placeholder="例如：会议与活动资料"></div><div class="fld"><label for="kwFolderDescription">说明</label><textarea class="ta" id="kwFolderDescription" maxlength="200" placeholder="说明目录用途，方便后续查找"></textarea></div>`,action('取消','cancelDialog()')+action('确定','saveFolder()','pri'));$('#kwFolderName').focus();},
    saveFolder(){const c=state.folderContext,name=$('#kwFolderName').value.trim(),description=$('#kwFolderDescription').value.trim();if(!name)return toast('请输入目录名称','warn');if(/[\\/<>]/.test(name))return toast('目录名称不能包含斜杠或尖括号','warn');if(nodes.some(n=>n.scope===c.scope&&(n.dept||null)===(c.dept||null)&&n.parent===c.parent&&n.name===name))return toast('当前目录已存在同名项目','warn');if(c.parent&&!nodes.some(n=>n.id===c.parent))return toast('上级目录已不存在','warn');const n={...c,id:'node-'+(++serial),kind:'folder',name,summary:description||'暂无摘要',overview:description||'目录尚未添加说明和资源。'};nodes.push(n);state.selected[scopeKey()]=n.id;if(c.parent)state.expanded.add(c.parent);closeAll();render();},
    chooseDept(){dlg('选择部门','<input class="inp" placeholder="输入部门名称过滤" aria-label="搜索部门" oninput="KW.deptFilter(this.value)"><div class="kw-depts" id="kwDepts">'+KW.deptItems('')+'</div>');},
    deptItems(q){return departments.filter(d=>d.name.includes(q)).map(d=>`<button onclick="KW.selectDept('${d.id}')">${d.name}<span class="kw-muted">${d.exists?' · 已有知识库':' · 尚未创建知识库'}</span></button>`).join('')||'<p class="kw-muted">没有匹配的部门</p>';},
    deptFilter(q){$('#kwDepts').innerHTML=KW.deptItems(q);},
    selectDept(id){const d=departments.find(d=>d.id===id);if(!d?.exists)return toast('该部门尚未创建部门库，请先添加','warn');state.dept=id;state.filter='';closeAll();render();},
    addDept(){dlg('添加部门库',`<div class="fld"><label for="kwDept">所属部门 *</label><select class="sel" id="kwDept"><option value="">请选择未创建部门库的部门</option>${departments.map(d=>`<option value="${d.id}" ${d.exists?'disabled':''}>${d.name}${d.exists?'（已创建）':''}</option>`).join('')}</select></div><div class="fld"><label for="kwDeptDescription">说明</label><textarea class="ta" id="kwDeptDescription" maxlength="200" placeholder="不超过 200 字"></textarea></div>`,action('取消','cancelDialog()')+action('确定','saveDept()','pri'));},
    saveDept(){const d=departments.find(d=>d.id===$('#kwDept').value);if(!d)return toast('请选择部门','warn');if(d.exists)return toast('该部门已存在知识库','warn');const desc=$('#kwDeptDescription').value.trim();if(desc.length>200)return toast('说明不能超过200字','warn');d.exists=true;d.description=desc;state.dept=d.id;closeAll();render();},
    remove(id){const n=nodes.find(n=>n.id===id);if(!n)return;dlg('删除'+(n.kind==='folder'?'目录':'资源'),`<p>确认删除「${escText(n.name)}」？${n.kind==='folder'?'其中的子目录与文件也会移除。':''}</p><p class="kw-muted">删除后不再参与新的知识库问答。</p>`,action('取消','cancelDialog()')+action('确认删除',`confirmRemove('${id}')`,'dgr'));},
    confirmRemove(id){const gone=new Set([id]);let changed=true;while(changed){changed=false;for(const n of nodes)if(gone.has(n.parent)&&!gone.has(n.id)){gone.add(n.id);changed=true;}}for(let i=nodes.length-1;i>=0;i--)if(gone.has(nodes[i].id))nodes.splice(i,1);for(const k of Object.keys(state.selected))if(gone.has(state.selected[k]))delete state.selected[k];closeAll();render();},
    upload(){const n=selected(),target=n?.kind==='folder'?n:nodes.find(x=>x.id===n?.parent);if(!target)return toast('请先选择一个目录','warn');state.uploadToken++;state.pending=[];state.uploadBusy=false;state.uploadTarget=target.id;state.uploadContext={scope:target.scope,dept:target.dept};dlg('添加本地资源',`<p class="kw-muted">上传到：${escText(target.name)}</p><label class="kw-drop" id="kwDrop">将文件拖到此处，或点击选择<input type="file" id="kwFiles" multiple hidden onchange="KW.pick(this.files);this.value=''"> </label><p class="kw-muted">支持 PDF、Word、PPTX、Excel、Markdown、代码文件、图片</p><div class="kw-files" id="kwFilesList"></div>`,action('取消','cancelUpload()')+'<button class="btn pri" id="kwImport" disabled onclick="KW.importFiles()">上传并导入</button>');const drop=$('#kwDrop');drop.ondragover=e=>e.preventDefault();drop.ondrop=e=>{e.preventDefault();KW.pick(e.dataTransfer.files);};},
    pick(files){if(state.uploadBusy)return;for(const f of Array.from(files||[])){if(!f.size){toast('空文件无法导入','warn');continue;}if(state.pending.some(x=>x.name===f.name&&x.size===f.size))continue;state.pending.push(f);}KW.fileList();},
    fileList(){if(!$('#kwFilesList'))return;$('#kwFilesList').innerHTML=state.pending.map((f,i)=>`<div class="kw-file"><span>${escText(f.name)} · ${Math.max(1,Math.round(f.size/1024))} KB</span><button ${state.uploadBusy?'disabled':''} aria-label="移除 ${escText(f.name)}" onclick="KW.unpick(${i})">移除</button></div>`).join('');$('#kwImport').disabled=!state.pending.length||state.uploadBusy;},
    unpick(i){if(!state.uploadBusy){state.pending.splice(i,1);KW.fileList();}},
    cancelDialog(){closeAll();},
    cancelUpload(){state.uploadToken++;state.pending=[];state.uploadBusy=false;closeAll();},
    async importFiles(){if(state.uploadBusy||!state.pending.length)return;const token=++state.uploadToken,target=state.uploadTarget,context={...state.uploadContext},files=[...state.pending];state.uploadBusy=true;KW.fileList();$('#kwImport').textContent='正在读取…';const results=[];let failed=0;for(const f of files){const readable=/\.(txt|md|csv|json|js|ts|py|html|css|java|go|sql)$/i.test(f.name);let text='';try{if(readable)text=await f.text();}catch{failed++;continue;}results.push({...context,id:'node-'+(++serial),parent:target,kind:'file',name:f.name,size:Math.max(1,Math.round(f.size/1024))+' KB',file:f,text,summary:readable?'已读取文件，尚未生成内容摘要。':'等待内容处理',overview:readable?text:'文件已加入，内容摘要和概览尚未生成。',pending:!readable});}if(token!==state.uploadToken)return;state.uploadBusy=false;if(!nodes.some(n=>n.id===target))return toast('目标目录已删除，文件未导入','warn');let duplicates=0;for(const n of results){if(nodes.some(x=>x.parent===target&&x.name===n.name)){duplicates++;continue;}nodes.push(n);}state.expanded.add(target);state.pending=[];closeAll();render();toast(failed||duplicates?`已添加可用文件，${failed} 个读取失败，${duplicates} 个同名文件未覆盖`:'文件已添加；摘要将在内容处理后显示',failed||duplicates?'warn':'ok');},
    download(id){const n=nodes.find(n=>n.id===id);if(!n||n.kind!=='file')return;const blob=n.file||new Blob([n.text||''],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=n.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},
    filesQuery(){state.fileQ=$('#kwFileQ').value.trim();state.fileScope=$('#kwFileScope').value;state.fileStatus=$('#kwFileStatus').value;state.filePage=1;$('#kwAccessibleFiles').innerHTML=filesHTML();},
    filesReset(){state.fileQ=state.fileScope=state.fileStatus='';state.filePage=1;render();},
    filePage(d){state.filePage=Math.max(1,state.filePage+d);$('#kwAccessibleFiles').innerHTML=filesHTML();},
    fileSize(n){state.fileSize=Number(n);state.filePage=1;$('#kwAccessibleFiles').innerHTML=filesHTML();},
    openFile(id){const n=nodes.find(n=>n.id===id&&n.kind==='file');if(!n)return toast('该文件已不可查看','warn');state.scope=n.scope;state.dept=n.scope==='dept'?n.dept:null;state.selected[scopeKey()]=n.id;if(n.parent)state.expanded.add(n.parent);state.filter='';go('kb-library');},
    draft(text){state.draft=text;const b=$('#kwSend');if(b&&!state.busy)b.disabled=!text.trim();},
    ask(q){state.draft=q;KW.send();},
    newChat(){if(state.busy)return;state.active=null;state.draft='';render();},
    history(){if(state.busy)return;dlg('历史会话',`<p class="kw-muted">当前浏览器会话中使用过的对话</p>${state.sessions.length?state.sessions.map(s=>`<button class="kw-history" onclick="KW.resume('${s.id}')"><b>${escText(s.title)}</b><span>${escText(s.at)} · ${s.messages.filter(m=>m.role==='user').length} 次提问</span></button>`).join(''):empty('暂无历史会话','发送第一个问题后，会话会出现在这里。')}`);},
    resume(id){if(state.busy||!state.sessions.some(s=>s.id===id))return;state.active=id;state.draft='';closeAll();render();},
    async send(){const question=state.draft.trim();if(state.busy||!question)return;const s=ensureSession();if(!s.messages.length)s.title=question.slice(0,50);s.messages.push({role:'user',text:question});const answer={role:'assistant',loading:true,text:'',steps:['查找当前账号可访问的资料']};s.messages.push(answer);state.draft='';state.busy=true;const ticket=++state.request;render();await new Promise(resolve=>setTimeout(resolve,350));if(ticket!==state.request)return;const files=nodes.filter(n=>n.kind==='file'&&!n.pending&&n.text);let matched=[];if(/有哪些|文档列表|最近更新/.test(question)){matched=files;answer.text=files.length?'当前可查阅的文档：\n'+files.map(n=>'• '+n.name+'（'+scopes[n.scope]+'）').join('\n'):'当前没有可读取的知识库资料。';}else{let lookup=question;if(/^(那|它|这|继续|具体|再)/.test(question)){const prev=s.messages.slice(0,-2).reverse().find(m=>m.role==='assistant'&&m.sources?.length);matched=(prev?.sources||[]).map(id=>files.find(f=>f.id===id)).filter(Boolean);}if(!matched.length)matched=files.filter(n=>{const title=n.name.replace(/\.[^.]+$/,'');return title.length>=2&&lookup.includes(title)||/会议|筹备/.test(lookup)&&/会议/.test(n.name)||/流转|归档/.test(lookup)&&/流转/.test(n.name)||/协作|交接/.test(lookup)&&/协作/.test(n.name);});answer.text=matched.length?matched.map(n=>`${n.name}\n${n.text}`).join('\n\n'):'未找到可以直接支撑这个问题的资料。请补充文件名称、业务关键词或相关内容。';}answer.sources=matched.map(n=>n.id);answer.steps.push(matched.length?`找到 ${matched.length} 份可用资料，展示相关内容`:'未取得可支持回答的资料');answer.loading=false;state.busy=false;if(cur==='qa')render();},
    stop(){if(!state.busy)return;state.request++;state.busy=false;const m=session()?.messages.findLast(m=>m.loading);if(m){m.loading=false;m.stopped=true;m.text='本次回答已停止。';}if(cur==='qa')render();},
    copy(index){const m=session()?.messages[index];if(m)copyText(m.text);},
    source(id){const n=nodes.find(n=>n.id===id);if(!n)return toast('该资料已移除','warn');dlg('来源内容',`<h4>${escText(n.name)}</h4><p class="kw-muted">${scopes[n.scope]}</p><div class="kw-details-text" style="max-height:55vh;overflow:auto;margin-top:16px">${escText(n.text)}</div>`);},
    inspect(){return {nodes:JSON.parse(JSON.stringify(nodes.map(({file,...n})=>n))),scope:state.scope,dept:state.dept,busy:state.busy,active:state.active,sessions:JSON.parse(JSON.stringify(state.sessions))};}
  };
  ROUTES.kb={nav:'kb',crumb:()=>crumbOf('知识库管理','营运总览'),html:overviewHTML};
  ROUTES['kb-library']={nav:'kb',crumb:()=>crumbOf('知识库管理',scopes[state.scope]),html:workspaceHTML};
  // Old entry points no longer expose the superseded slice-governance workflow.
  for(const route of ['kb-docs','kb-doc','kb-detail','kb-upload'])ROUTES[route]=ROUTES['kb-library'];
  ROUTES.qa={nav:'qa',crumb:()=>crumbOf('知识库问答',session()?.title||'新建会话'),html:chatHTML,init(){const input=$('#kwQuestion');input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();KW.send();}};const body=$('#kwChatBody');body.scrollTop=body.scrollHeight;}};
  const originalGo=go;
  go=function(v,c={}){if(cur==='qa'&&v!=='qa'&&state.busy)KW.stop();if(state.uploadBusy)KW.cancelUpload();return originalGo(v,c);};
  const originalClose=closeAll;
  closeAll=function(){if(state.uploadBusy){state.uploadToken++;state.uploadBusy=false;}originalClose();};
  $('#mask').onclick=()=>closeAll();
  const originalRecent=openRecent;
  openRecent=function(i){const r=RECENT[i];if(r?.v==='qa'){if(state.busy)KW.stop();state.active=null;state.draft=r.q||r.t;go('qa');return;}return originalRecent(i);};
  qaNew=()=>KW.newChat();
  qaAsk=q=>KW.ask(q);
  const homeHTML=ROUTES.home.html;
  ROUTES.home.html=function(...args){return homeHTML(...args).replace(`${totalDocs().toLocaleString()}</b><span>知识库文档`,`${nodes.filter(n=>n.kind==='file').length}</b><span>知识库文档`);};
  render();
})();
